import{_ as i,l as n,o as a,c as m,v as e,p as s,x as r,d,i as h,S as l}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"连续时间预算约束","description":"","frontmatter":{"title":"连续时间预算约束","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/continuous-time-budget.md","filePath":"econ/continuous-time-budget.md","lastUpdated":1789023840000}'),p={name:"econ/continuous-time-budget.md"};function c(E,t,u,_,B,A){const o=n("Mermaid");return a(),m("div",null,[t[1]||(t[1]=e('<h1 id="连续时间预算约束" tabindex="-1">连续时间预算约束 <a class="header-anchor" href="#连续时间预算约束" aria-label="Permalink to &quot;连续时间预算约束&quot;">​</a></h1><div class="epigraph"><p>财富的微分等于资本利得加利息减消费；伊藤项让预算本身成为随机微分方程，而不是每期的算术和。</p><footer>—— 据 Merton, Optimum Consumption and Portfolio Rules in a Continuous-Time Model, JET 1971</footer></div><p><a href="/econ/brownian-ito">上一课</a>给出 \\(\\mathrm{d}f\\) 的公式。本课缺口是把公式写成<strong>预算</strong>：消费率 \\(c_t\\)、组合权重 \\(\\theta_t\\) 如何驱动 \\(W_t\\)。不求解最优，\\(\\theta\\) 与 \\(c\\) 仍是任意适应过程（满足正则）。后课 Merton 问题才对它们取最大值。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>离散： \\(W_{t+1}=(W_t-C_t)(1+R_{p,t+1})\\)。连续极限：设无风险 \\(r\\)，风险资产 \\(\\mathrm{d}S/S=\\mu\\mathrm{d}t+\\sigma\\mathrm{d}B\\)，权重 \\(\\theta\\) 在风险资产上，则</p> \\[\\mathrm{d}W=\\bigl[rW+\\theta W(\\mu-r)-c\\bigr]\\mathrm{d}t+\\theta W\\sigma\\,\\mathrm{d}B. \\]<p>这是状态的动力学。横截或非负财富排除加倍。缺口是承认：连续时间的可行性是对这道 SDE 的积分，消费是速率，组合是暴露。需求系统的「份额」在此变成 \\(\\theta\\)；没有特征 logit，只有暴露于 \\(B\\) 的系数。</p><p><span class="marginnote">Merton, <em>JET</em> 3, 1971。劳动收入、多个布朗、随机 \\(r\\)，只是把 \\(\\mathrm{d}W\\) 加项。本课先单一风险资产、常系数，便于看见结构。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>从自融资出发：除消费外没有注入，持仓的价值变化全部来自价格变化。伊藤乘法给出 \\(\\theta\\) 进入漂移与扩散的方式——扩散只被风险暴露驱动，消费只进漂移。这与 FTAP 衔接：\\(\\mathrm{d}W\\) 的扩散若能被 \\(\\theta\\) 对冲掉任意 \\(\\mathcal{F}\\)–适应的目标（在完全时），复制就是选 \\(\\theta\\)。预算是复制与最优的共同约束。</p>',10)),(a(),s(l,null,{default:r(()=>[h(o,{id:"mermaid-26",class:"mermaid",graph:"flowchart%20TD%0A%20%20SELF%5B%22%E8%87%AA%E8%9E%8D%E8%B5%84%22%5D%20--%3E%20SDE%5B%22dW%20%3D%20(rW%20%2B%20%CE%B8W(%CE%BC-r)%20-%20c)%20dt%20%2B%20%CE%B8W%CF%83%20dB%22%5D%0A%20%20SDE%20--%3E%20DRIFT%5B%22c%20%E4%B8%8E%E8%B6%85%E9%A2%9D%E5%8F%AA%E8%BF%9B%E6%BC%82%E7%A7%BB%22%5D%0A%20%20SDE%20--%3E%20DIFF%5B%22%CE%B8%20%E5%86%B3%E5%AE%9A%E6%89%A9%E6%95%A3%22%5D%0A%20%20DIFF%20--%3E%20NEXT%5B%22%E4%B8%8B%E4%B8%80%E8%AF%BE%3A%20%E9%80%89%20%CE%B8%20%E4%B8%8E%20c%22%5D%0A"})]),fallback:r(()=>[...t[0]||(t[0]=[d(" Loading... ",-1)])]),_:1})),t[2]||(t[2]=e('<p>不要把 \\(\\mathrm{d}W\\) 写成每笔成交后的现金账户。连续时间没有逐笔：是理想化的再平衡。价差下再平衡有成本，Constantinides 后课把预算改成区间策略。本课零成本。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制是暴露与消耗分开记账。消费降低漂移，立刻减少未来投资的基数；风险暴露同时提高（或降低）漂移里的超额，并打开扩散。二次变差使 \\(W\\) 的凹变换（如 \\(\\log W\\)）多一项 \\(-\\tfrac12\\theta^2\\sigma^2\\)，即便 \\(\\mathrm{E}[\\mathrm{d}W]\\) 看起来很美。这就是后文最优会惩罚 \\(\\theta\\) 的原因——在预算里已经藏了 Jensen，不只在效用里。</p><p>多个资产：\\(\\theta\\) 成向量，\\(\\sigma\\) 成矩阵，扩散维数等于独立布朗数。维数不够则预算张不成任意终端财富，回到动态不完全。维数对齐则本课的 SDE 是完全市场的预算。</p><p><span class="marginnote">随机利率：债券价格也扩散，\\(W\\) 多暴露一项，后文对冲需求正是为了对付这项。本课 \\(r\\) 为常数，对冲还没有对象。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不谈存在唯一强解的 Lipschitz 条件。下一课在这道预算上最大化 \\(\\mathrm{E}\\int u(c)\\,\\mathrm{d}t\\)（加遗产），得到 Merton 权重。ICAPM 主干课已经用过对冲的结果；本单元从预算重新走到那条结果，并停在组合理论，不重写截面因子。</p><p>后课默认：连续时间预算是自融资 SDE；消费进漂移，组合进漂移与扩散。财富下界排除加倍。零交易成本。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>\\(\\mathrm{d}W=[rW+\\theta W(\\mu-r)-c]\\mathrm{d}t+\\theta W\\sigma\\mathrm{d}B\\)。</li><li>自融资：无注入；扩散由风险暴露单独决定。</li><li>这是最优与复制的共同约束，还不是最优。</li><li>出处：Merton, <em>JET</em> 1971。</li></ul>',10))])}const W=i(p,[["render",c]]);export{T as __pageData,W as default};
